//		Exec(ctx)
func (_c *KnowledgeEvidenceCreateBulk) OnConflictColumns(columns ...string) *KnowledgeEvidenceUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &KnowledgeEvidenceUpsertBulk{
		create: _c,
	}
}

// KnowledgeEvidenceUpsertBulk is the builder for "upsert"-ing
// a bulk of KnowledgeEvidence nodes.
type KnowledgeEvidenceUpsertBulk struct {
	create *KnowledgeEvidenceCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.KnowledgeEvidence.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(knowledgeevidence.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *KnowledgeEvidenceUpsertBulk) UpdateNewValues() *KnowledgeEvidenceUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(knowledgeevidence.FieldID)
			}
			if _, exists := b.mutation.TenantID(); exists {
				s.SetIgnore(knowledgeevidence.FieldTenantID)
			}
			if _, exists := b.mutation.EventID(); exists {
				s.SetIgnore(knowledgeevidence.FieldEventID)
			}
			if _, exists := b.mutation.Assertion(); exists {
				s.SetIgnore(knowledgeevidence.FieldAssertion)
			}
			if _, exists := b.mutation.EvidenceKind(); exists {
				s.SetIgnore(knowledgeevidence.FieldEvidenceKind)
			}
			if _, exists := b.mutation.AliasID(); exists {
				s.SetIgnore(knowledgeevidence.FieldAliasID)
			}
			if _, exists := b.mutation.EffectiveAt(); exists {
				s.SetIgnore(knowledgeevidence.FieldEffectiveAt)
			}
			if _, exists := b.mutation.Properties(); exists {
				s.SetIgnore(knowledgeevidence.FieldProperties)
			}
			if _, exists := b.mutation.SubjectState(); exists {
				s.SetIgnore(knowledgeevidence.FieldSubjectState)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.KnowledgeEvidence.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *KnowledgeEvidenceUpsertBulk) Ignore() *KnowledgeEvidenceUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *KnowledgeEvidenceUpsertBulk) DoNothing() *KnowledgeEvidenceUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the KnowledgeEvidenceCreateBulk.OnConflict
// documentation for more info.
func (u *KnowledgeEvidenceUpsertBulk) Update(set func(*KnowledgeEvidenceUpsert)) *KnowledgeEvidenceUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&KnowledgeEvidenceUpsert{UpdateSet: update})
	}))
	return u
}

